 Here's an example C++ program that generates a Fibonacci sequence using a recursive function. This program takes the first two sequence elements as user input and the number of sequence elements to generate. It includes error handling for non-numeric inputs and negative numbers.

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

long long fib(int n, int a, int b) {
    if (n <= 0) throw invalid_argument("Invalid input: n must be positive.");
    if (!isdigit(a + '0') || !isdigit(b + '0')) throw invalid_argument("Invalid input: a and b must be digits.");
    if (n == 1) return a;
    if (n == 2) return a + b;
    return fib(n - 1, b, a + b);
}

void printFibSequence(int numElements) {
    if (numElements <= 0) throw invalid_argument("Invalid input: numElements must be positive.");

    cout << "The first " << numElements << " numbers in the Fibonacci sequence are:" << endl;

    try {
        cout << fib(numElements, 0, 1) << ", ";
        for (int i = 1; i < numElements; ++i) {
            cout << fib(i, static_cast<int>(fib(i - 1, 0, 1)), fib(i - 1, 0, 1)) << ", ";
        }
        cout << "\b\b"; // remove last comma and space
    } catch (invalid_argument& e) {
        cerr << "Error: " << e.what() << endl;
    }
}

