```javascript
function determineProtocol(inputData) {
  let ipVersion;
  if (isValidIPv6(inputData.sourceIP) && isValidIPv6(inputData.destinationIP)) {
    ipVersion = "IPv6";
  } else {
    // Assuming IPv4 is the default as it's more common and the given input doesn't specify otherwise
    ipVersion = "IPv4";
  }

  if (ipVersion === "IPv6") {
    // IPv6 uses both UDP and TCP for various applications but IPv6 over IPv6 is preferred for IPv6 addresses communication
    if (inputData.port >= 1 && inputData.port <= 65535) {
      if (inputData.protocol === undefined || inputData.protocol === null || inputData.protocol.toUpperCase() === "HTTP".toUpperCase()) {
        return "HTTP"; // IPv6 with port 80 is typically HTTP
      } else {
        return "UDP"; // Other applications like VoIP or DNS can use UDP with IPv6
      }
    } else {
      return ipVersion; // Invalid port number for given IP version
