function findNestedKeyValue(obj, strKey) {
  let currentKey, currentValue;
  const keys = strKey.split("."); // Split the given string into keys by "."

  for (const key of keys) {
    if (currentValue && currentValue[key]) {
      currentValue = currentValue[key];
    } else {
      currentKey = obj[key];
      currentValue = undefined; // Reset currentValue before checking next level
    }

    if (typeof currentValue === "undefined") {
      throw new Error(`Key "${strKey}" not found in object.`);
    }
  }

  return currentValue;
}

