import App from './App';
import { ToastProvider } from './ToastContext';

ReactDOM.render(
  <React.StrictMode>
    <ToastProvider>
      <App />
    </ToastProvider>
  </React.StrictMode>,
  document.getElementById('root')
);
```

3. Create a `Toast` component that will display the toast message when passed as a prop:

```javascript
// Create a new file Toast.js
import React from 'react';
import { useContext } from 'react';
import { ToastContext } from './ToastContext';

const Toast = () => {
  const { toastMessage } = useContext(ToastContext);

  if (!toastMessage) return null;

  return (
    <div className="toast">
      <p>{toastMessage}</p>
    </div>
  );
};

export default Toast;
```

